import pytest

from revtrans import GENETIC_CODE, CODON_FREQUENCIES, revtrans, translate


def test_known_answer():
    assert revtrans("MAIVMGR") == "ATGGCGATTGTGATGGGCCGC"


def test_best_codons_match_frequency_table():
    for aa, codons in CODON_FREQUENCIES.items():
        best = max(codons.values())
        from revtrans import BEST_CODON
        assert codons[BEST_CODON[aa]] == best


def test_round_trip():
    protein = "MAIVMGR"
    assert translate(revtrans(protein)) == protein


def test_unknown_residue_raises_keyerror():
    with pytest.raises(KeyError, match="X"):
        revtrans("MAIVXGR")


def test_empty_sequence():
    assert revtrans("") == ""

